486	+
487	+public class SeatMapServiceTests
488	+{
489	+    private static AppDbContext CreateContext(string dbName)
490	+    {
491	+        var options = new DbContextOptionsBuilder<AppDbContext>()
492	+            .UseInMemoryDatabase(dbName)
493	+            .Options;
494	+        return new AppDbContext(options);
495	+    }
496	+
497	+    private static async Task<(Venue Venue, Room Room, Event Event)> SeedRoomWithEventAsync(AppDbContext dbContext)
498	+    {
499	+        var venue = new Venue { Id = Guid.NewGuid(), Name = "Stadthalle Nordpark" };
500	+        var room = new Room
501	+        {
502	+            Id = Guid.NewGuid(),
503	+            Name = "Kleiner Saal",
504	+            VenueId = venue.Id,
505	+            Reihen = new List<string> { "A", "B" },
506	+            SpaltenAnzahl = 3,
507	+            GangSpalten = new List<int> { 2 }
508	+        };
509	+        dbContext.Venues.Add(venue);
510	+        dbContext.Rooms.Add(room);
511	+
512	+        foreach (var reihe in room.Reihen)
513	+        {
514	+            dbContext.Seats.Add(new Seat { Id = Guid.NewGuid(), RoomId = room.Id, Row = reihe, Column = 1 });
515	+            dbContext.Seats.Add(new Seat { Id = Guid.NewGuid(), RoomId = room.Id, Row = reihe, Column = 3 });
516	+        }
517	+
518	+        var @event = new Event
519	+        {
520	+            Id = Guid.NewGuid(),
521	+            Titel = "Kammerkonzert",
522	+            Beschreibung = "b",
523	+            DauerMinuten = 90,
524	+            Altersfreigabe = 0,
525	+            Zeitpunkt = new DateTime(2026, 9, 5, 19, 30, 0, DateTimeKind.Unspecified),
526	+            VenueId = venue.Id,
527	+            RoomId = room.Id
528	+        };
529	+        dbContext.Events.Add(@event);
530	+
531	+        await dbContext.SaveChangesAsync();
532	+
533	+        return (venue, room, @event);
534	+    }
535	+
536	+    [Fact]
537	+    public async Task GetSeatMapAsync_ReturnsFullGridWithAisleColumnsAndFreeSeats()
538	+    {
539	+        using var dbContext = CreateContext(nameof(GetSeatMapAsync_ReturnsFullGridWithAisleColumnsAndFreeSeats));
540	+        var (_, _, @event) = await SeedRoomWithEventAsync(dbContext);
541	+
542	+        var service = new SeatMapService(dbContext);
543	+        var result = await service.GetSeatMapAsync(@event.Id);
544	+
545	+        Assert.NotNull(result);
546	+        Assert.Equal(new List<string> { "A", "B" }, result!.Rows);
547	+        Assert.Equal(3, result.Columns);
548	+        Assert.Equal(new List<int> { 2 }, result.AisleColumns);
549	+        Assert.Equal(4, result.Seats.Count);
550	+        Assert.All(result.Seats, s => Assert.Equal(SeatStatus.Free, s.Status));
551	+    }
