31	+{
32	+    public async Task<SeatMapDto?> GetSeatMapAsync(Guid eventId)
33	+    {
34	+        var roomId = await dbContext.Events
35	+            .Where(e => e.Id == eventId)
36	+            .Select(e => (Guid?)e.RoomId)
37	+            .FirstOrDefaultAsync();
38	+
39	+        if (roomId is null)
40	+        {
41	+            return null;
42	+        }
43	+
44	+        var room = await dbContext.Rooms
45	+            .Where(r => r.Id == roomId.Value)
46	+            .Select(r => new { r.Reihen, r.SpaltenAnzahl, r.GangSpalten })
47	+            .FirstAsync();
48	+
49	+        var seats = await dbContext.Seats
50	+            .Where(s => s.RoomId == roomId.Value)
51	+            .OrderBy(s => s.Row)
52	+            .ThenBy(s => s.Column)
53	+            .Select(s => new SeatDto(s.Id, s.Row, s.Column, SeatStatus.Free))
54	+            .ToListAsync();
55	+
56	+        return new SeatMapDto(eventId, room.Reihen, room.SpaltenAnzahl, room.GangSpalten, seats);
